guardrail.good:
#[get("/users/<id>")]
async fn get_user(mut db: DbConn, id: &str) -> Result<Json<User>, AppError> {
    let user = get_from_db(&mut db, id).await
        .map_err(AppError::Database)?
        .ok_or_else(|| AppError::NotFound("user not found".into()))?;
    Ok(Json(user))
}

