entry-point.example:
#[macro_use] extern crate rocket;

use rocket::{Build, Rocket};
use rocket_db_pools::Database;

#[launch]
fn rocket() -> Rocket<Build> {
    dotenvy::dotenv().ok();

    rocket::build()
        .attach(DbPool::init())              // database pool — must come first
        .attach(fairings::RequestLogger)     // request/response logging fairing
        .attach(fairings::Cors)              // CORS headers fairing
        .mount("/api", routes::api_routes())
        .mount("/health", routes::health_routes())
        .manage(config::AppConfig::default())
        .register("/", catchers![
            error::not_found,
            error::internal_error,
            error::unauthorized,
            error::bad_request,
        ])
}

request-guards.example:
#[derive(Debug)]
pub struct AuthUser {
    pub user_id: Uuid,
    pub email: String,
    pub role: String,
}

#[rocket::async_trait]
impl<'r> FromRequest<'r> for AuthUser {
    type Error = AppError;

    async fn from_request(request: &'r Request<'_>) -> Outcome<Self, Self::Error> {
        let token = match request.headers().get_one("Authorization") {
            Some(h) if h.starts_with("Bearer ") => &h[7..],
            _ => return Outcome::Error((
                Status::Unauthorized,
                AppError::Unauthorized("Missing Authorization header".into()),
            )),
        };

        match verify_jwt(token, &get_jwt_secret()) {
            Ok(claims) => Outcome::Success(AuthUser {
                user_id: claims.sub,
                email: claims.email,
                role: claims.role,
            }),
            Err(_) => Outcome::Error((
                Status::Unauthorized,
                AppError::Unauthorized("Invalid or expired token".into()),
            )),
        }
    }
}

// Role-based guard by composing AuthUser
pub struct AdminUser(pub AuthUser);

#[rocket::async_trait]
impl<'r> FromRequest<'r> for AdminUser {
    type Error = AppError;

    async fn from_request(request: &'r Request<'_>) -> Outcome<Self, Self::Error> {
        match AuthUser::from_request(request).await {
            Outcome::Success(user) if user.role == "admin" => Outcome::Success(AdminUser(user)),
            Outcome::Success(_) => Outcome::Error((
                Status::Forbidden,
                AppError::Unauthorized("Admin access required".into()),
            )),
            Outcome::Error(e) => Outcome::Error(e),
            Outcome::Forward(s) => Outcome::Forward(s),
        }
    }
}

error-handling.example:
#[derive(Error, Debug)]
pub enum AppError {
    #[error("Not found: {0}")]
    NotFound(String),
    #[error("Unauthorized: {0}")]
    Unauthorized(String),
    #[error("Validation: {0}")]
    Validation(String),
    #[error("Database error")]
    Database(#[from] sqlx::Error),
    #[error("Internal: {0}")]
    Internal(String),
}

impl<'r> Responder<'r, 'static> for AppError {
    fn respond_to(self, request: &'r Request<'_>) -> response::Result<'static> {
        let (status, body) = match &self {
            AppError::NotFound(m) => (Status::NotFound, json!({"error": m})),
            AppError::Unauthorized(m) => (Status::Unauthorized, json!({"error": m})),
            AppError::Validation(m) => (Status::BadRequest, json!({"error": m})),
            AppError::Database(e) => {
                eprintln!("Database error: {:?}", e);
                (Status::InternalServerError, json!({"error": "database error"}))
            }
            AppError::Internal(m) => {
                eprintln!("Internal error: {}", m);
                (Status::InternalServerError, json!({"error": "internal error"}))
            }
        };
        Response::build_from(Json(body).respond_to(request)?)
            .status(status)
            .ok()
    }
}

// Catchers
#[catch(404)]
pub fn not_found() -> Json<Value> { Json(json!({"error": "not found"})) }

#[catch(401)]
pub fn unauthorized() -> Json<Value> { Json(json!({"error": "unauthorized"})) }

#[catch(500)]
pub fn internal_error() -> Json<Value> { Json(json!({"error": "internal error"})) }

#[catch(400)]
pub fn bad_request() -> Json<Value> { Json(json!({"error": "bad request"})) }

fairings.example:
pub struct RequestLogger;

#[rocket::async_trait]
impl Fairing for RequestLogger {
    fn info(&self) -> Info {
        Info { name: "Request Logger", kind: Kind::Request | Kind::Response }
    }

    async fn on_request(&self, request: &mut Request<'_>, _: &mut Data<'_>) {
        request.local_cache(|| std::time::Instant::now());
    }

    async fn on_response<'r>(&self, request: &'r Request<'_>, response: &mut Response<'r>) {
        let start = request.local_cache(|| std::time::Instant::now());
        println!("{} {} {} {:?}",
            request.method(), request.uri(),
            response.status().code, start.elapsed());
    }
}

pub struct Cors;

#[rocket::async_trait]
impl Fairing for Cors {
    fn info(&self) -> Info { Info { name: "CORS", kind: Kind::Response } }

    async fn on_response<'r>(&self, _: &'r Request<'_>, response: &mut Response<'r>) {
        response.set_header(Header::new("Access-Control-Allow-Origin", "*"));
        response.set_header(Header::new("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS"));
        response.set_header(Header::new("Access-Control-Allow-Headers", "Content-Type, Authorization"));
    }
}

database.example:
use rocket_db_pools::{sqlx, Database, Connection};

#[derive(Database)]
#[database("db_pool")]
pub struct DbPool(sqlx::PgPool);

pub type DbConn = Connection<DbPool>;

// Usage in handler
#[get("/users/<id>")]
pub async fn get_user(
    mut db: DbConn,
    id: Uuid,
    _auth: AuthUser,
) -> Result<Json<UserResponse>, AppError> {
    let user = sqlx::query_as::<_, User>("SELECT * FROM users WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut **db)
        .await
        .map_err(AppError::Database)?
        .ok_or_else(|| AppError::NotFound("user not found".into()))?;
    Ok(Json(user.into()))
}

testing.example:
use rocket::local::asynchronous::Client;
use rocket::http::Status;

#[rocket::async_test]
async fn test_health_check() {
    let client = Client::tracked(rocket()).await.expect("valid rocket instance");
    let response = client.get("/health").dispatch().await;
    assert_eq!(response.status(), Status::Ok);
}

#[rocket::async_test]
async fn test_get_user_unauthenticated_returns_401() {
    let client = Client::tracked(rocket()).await.expect("valid rocket instance");
    let response = client.get("/api/users/some-id").dispatch().await;
    assert_eq!(response.status(), Status::Unauthorized);
}

#[rocket::async_test]
async fn test_not_found_catcher() {
    let client = Client::tracked(rocket()).await.expect("valid rocket instance");
    let response = client.get("/api/does-not-exist").dispatch().await;
    assert_eq!(response.status(), Status::NotFound);
    let body = response.into_string().await.unwrap();
    assert!(body.contains("not found"));
}
